export default {"html":"<p data-line=\"0\" class=\"code-line\">This article is part of the <a href=\"https://adventar.org/calendars/7114\" target=\"_blank\" rel=\"noopener noreferrer\">Ionic Framework / Capacitor / Stencil Advent Calendar 2021</a>.</p>\n<hr data-line=\"2\" class=\"code-line\">\n<p data-line=\"4\" class=\"code-line\">You often want to show a Loading Controller during network requests. If you write it directly in a page component without thinking, it looks like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"6\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">connectEvent</span><span style=\"color:#E1E4E8\">():</span><span style=\"color:#F97583\">void</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> loading</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.loadingController.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> loading.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.httpClient.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Type</span><span style=\"color:#E1E4E8\">&gt;(url)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    .</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      next</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {},</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      error</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {},</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      complete</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        loading.</span><span style=\"color:#B392F0\">dismiss</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"21\" class=\"code-line\">However, if you handle values here, everything ends up inline in the page component, which is tedious. Moving it to a service looks like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"23\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(): Observable</span><span style=\"color:#F97583\">&lt;</span><span style=\"color:#E1E4E8\">Type</span><span style=\"color:#F97583\">&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  return </span><span style=\"color:#B392F0\">from</span><span style=\"color:#E1E4E8\">(this.loadingController.create().</span><span style=\"color:#B392F0\">then</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">d</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> d.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">())).</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">    concatMap</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">httpClient</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Type</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#B392F0\">url</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            .</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">              finalize</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loadingController</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">dismiss</span><span style=\"color:#E1E4E8\">())</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ));</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"35\" class=\"code-line\">Because <code>loadingController.create()</code> is Promise-based, convert it with <code>from()</code>. Then use <code>concatMap</code> to tie it to the request, and call <code>dismiss</code> in <code>finalize</code> when the request completes.</p>\n<p data-line=\"37\" class=\"code-line\">With that, the page can be written like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"39\"><span class=\"line\"><span style=\"color:#B392F0\">connectEvent</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.service.</span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#79B8FF\">...</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"45\" class=\"code-line\">That alone shows the loading indicator and dismisses it when the request finishes.<br>\nTying request-related behavior to the service side and handling it automatically keeps page components easier to read. See you next time.</p>\n","headings":[]} as const;
